      (100, '유기농 야생 빌베리 루테인 파우더 100g', 'VITAL BOTANICS', '기타 건강식품', 'https://images.unsplash.com/photo-1464965911861-746a04b4bca6?w=600&auto=format&fit=crop&q=80', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Purple_potato_powder_and_blueberry_powder.jpg/960px-Purple_potato_powder_and_blueberry_powder.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail')
  ), updated as (
    update public.products as p
    set image_url = c.new_image_url
    from changes as c
    where p.product_id = c.product_id
      and p.name = c.name
      and p.brand = c.brand
      and p.category = c.category
      and p.image_url = c.old_image_url
      and p.image_url is distinct from c.new_image_url
    returning p.product_id
  )
  select count(*) into updated_count from updated;

  if updated_count <> 76 then
    raise exception 'Expected 76 image updates, but matched %. No changes committed. Check IDs, names and existing URLs.', updated_count;
  end if;
  raise notice 'Updated % product image URLs.', updated_count;
end;
$product_images$;

commit;
